           in:against ?coverage .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber .

    BIND(
      (xsd:dateTime(?closeDate) - xsd:dateTime(?openDate)) / "P1D"^^xsd:dayTimeDuration
      AS ?settlementDays
    )
  }
}
GROUP BY ?policyNumber
